import{_ as n,C as i,o,c as h,j as t,a,b as d,w as s,E as l,ap as c,ao as p}from"./chunks/framework.B6MdFEBY.js";const k=JSON.parse('{"title":"The shape of the system","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md","lastUpdated":null}'),u={name:"explanation/architecture.md"};function m(w,e,g,f,v,y){const r=i("Mermaid");return o(),h("div",null,[e[1]||(e[1]=t("h1",{id:"The-shape-of-the-system",tabindex:"-1"},[a("The shape of the system "),t("a",{class:"header-anchor",href:"#The-shape-of-the-system","aria-label":'Permalink to "The shape of the system {#The-shape-of-the-system}"'},"​")],-1)),e[2]||(e[2]=t("p",null,[a("The browser holds a small runtime called the "),t("strong",null,"Core"),a(". Every decision about what the scene contains lives in the Julia process, and reaches the Core as a "),t("strong",null,"module"),a("'s payload. The Core carries that payload to the module that owns it and never looks inside.")],-1)),(o(),d(c,null,{default:s(()=>[l(r,{id:"mermaid-6",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20julia%5B%22Julia%20process%22%5D%0A%20%20%20%20scene%5B%22your%20scene%20code%22%5D%0A%20%20%20%20cl%5B%22CesiumLink%22%5D%0A%20%20%20%20scene%20--%3E%20cl%0A%20%20end%0A%20%20subgraph%20browser%5B%22Browser%20page%22%5D%0A%20%20%20%20core%5B%22Core%22%5D%0A%20%20%20%20prim%5B%22primitives%22%5D%0A%20%20%20%20uimod%5B%22ui%22%5D%0A%20%20%20%20own%5B%22a%20module%20of%20your%20own%22%5D%0A%20%20%20%20core%20--%3E%20prim%0A%20%20%20%20core%20--%3E%20uimod%0A%20%20%20%20core%20--%3E%20own%0A%20%20end%0A%20%20cl%20%3C--%3E%7C%22one%20WebSocket%22%7C%20core%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=p('<h2 id="What-the-Core-owns" tabindex="-1">What the Core owns <a class="header-anchor" href="#What-the-Core-owns" aria-label="Permalink to &quot;What the Core owns {#What-the-Core-owns}&quot;">​</a></h2><p>The Core is the part of the browser side that no scene author writes and no module replaces. It owns eleven things.</p><ul><li><p><strong>The transport.</strong> One notification per frame, in either direction, with the array bytes behind it. The Core depends on that interface alone, and each host picks the transport under it: the browser host opens a binary WebSocket at <code>/ws</code>, same-origin with the page; the VSCode extension owns the socket and the panel reaches it over a message channel; a KaimonSlate cell borrows the socket that the notebook page already holds; a player reads a recording.</p></li><li><p><strong>The envelope.</strong> <code>{module, topic, payload}</code>. The Core routes on the first two fields alone.</p></li><li><p><strong>The clock.</strong> One clock for the whole page, set from the declared range a window states. A module reads it and never drives it.</p></li><li><p><strong>The window buffer.</strong> The delivered keyframes, their coverage, the eviction that bounds them, and the request that tops them up. See <a href="./windows">Windows, keyframes and identity</a>.</p></li><li><p><strong>Module loading.</strong> The version gate, the three-pass loader, and the teardown that drains what a module registered.</p></li><li><p><strong>Entity-ID namespacing.</strong> <code>ctx.pickId(kind, idx)</code> stamps a primitive with the module&#39;s own id. The Core drills past an unstamped primitive, so a decoration never masks what it covers.</p></li><li><p><strong>Pick dispatch.</strong> One <code>ScreenSpaceEventHandler</code>, one pixel read per pointer move, and a stack of owned hits offered to every local handler in turn (ADR-0003).</p></li><li><p><strong>Overlay regions.</strong> Four named positions on screen. A module contributes DOM and never positions it; the Core refuses the eight CSS properties that would move a region (ADR-0004).</p></li><li><p><strong>The array codec.</strong> The one thing the Core understands inside a payload. See <a href="./arrays">Arrays on the wire</a>.</p></li><li><p><strong>Same-origin assets.</strong> The page, the Cesium runtime and each declared module&#39;s directory come from the one process that holds the socket. So <code>import()</code> raises no CORS question, and the design works inside a webview under a strict <code>script-src</code>.</p></li><li><p><strong>Furniture.</strong> The ten items the Core puts on screen: the timeline ruler, the clock face, the keyframe readout and the camera-follow indicator along the bottom, and six corner buttons. The server declares which items are on screen as one set (ADR-0015).</p></li></ul><h2 id="What-the-Core-deliberately-does-not-do" tabindex="-1">What the Core deliberately does not do <a class="header-anchor" href="#What-the-Core-deliberately-does-not-do" aria-label="Permalink to &quot;What the Core deliberately does not do {#What-the-Core-deliberately-does-not-do}&quot;">​</a></h2><p>Three absences matter most.</p><p><strong>It models no entities.</strong> A satellite is a row of an array in a payload that <code>primitives</code> reads. The Core knows only that the payload holds an array, and that a keyframe addresses a block of it. If the Core learns what a family is, the payload stops being opaque. Every new scene shape then needs a word the browser already knows.</p><p><strong>It interpolates nothing.</strong> The module blends between two keyframes on every render tick. The Core states which keyframe brackets the current instant, and how far the blend has gone. It never throttles the blend: smooth motion is the reason the buffer exists.</p><p><strong>It never reads inside a payload.</strong> The one exception is the encoded array: the codec finds a three-field object at any nesting depth and replaces it with a typed array. So a decoder needs no schema, and a new payload shape needs no Core change.</p><p>Two smaller absences follow. The Core keeps no visibility state, because filtering is the server&#39;s answer (ADR-0007). It never drops a stale command batch, because only the receiving module knows whether a late answer is still worth having.</p><h2 id="Why-the-line-falls-there" tabindex="-1">Why the line falls there <a class="header-anchor" href="#Why-the-line-falls-there" aria-label="Permalink to &quot;Why the line falls there {#Why-the-line-falls-there}&quot;">​</a></h2><p>This package is for Julia users, and it assumes the computation is Julia&#39;s. The Julia side produces a frame faster than playback consumes it, and the socket delivers that frame faster still. A viewer that decides anything must first be sent what it decides with, and much of that is never drawn. One authority also keeps the contract small.</p><p>The alternative was a viewer that knows the domain: a satellite type, a filter language, and a new wire field for every new question anyone asks of the data. It also fails outright on one case. A mask cannot express a filter that changes <em>derived</em> values: a constellation restricted to one shell leaves cells unserved, and no per-entity visibility flag says that. <a href="./server-authoritative">Why the server decides</a> states the argument in full.</p><p>The line costs a round trip. The server answers a tooltip, a toggle and a click, so each costs a message up and a message down: a few milliseconds on the same host, and visible over a wide-area link. If that ever becomes a problem, the fix is a module-local immediate tier, which brings back the duplication this design removed (ADR-0010).</p><h2 id="Modules,-and-the-vendored-ones" tabindex="-1">Modules, and the vendored ones <a class="header-anchor" href="#Modules,-and-the-vendored-ones" aria-label="Permalink to &quot;Modules, and the vendored ones {#Modules,-and-the-vendored-ones}&quot;">​</a></h2><p>A module is one ES module whose default export has a <code>setup(ctx)</code>. The Core hands it a context object with every capability it may use: the shared Cesium namespace, the scene, the clock, the window and frame callbacks, pick stamps, overlay access, and the two functions that address a keyframe inside an array. A module imports Cesium for types only. Two live copies of Cesium in one page cannot share a scene, and the failure shows as blank geometry.</p><p>Four modules ship inside the viewer bundle: <code>primitives</code>, <code>ui</code>, <code>heatmap</code> and <code>models</code>. They are <strong>vendored</strong>: each is told only a shape, a value or a colour, and never a domain concept. <code>heatmap</code> is told a grid of colour over a box of degrees, and never whether the field is a rain fade. A module that must be told about rain fade ships from the package that owns that word.</p><p>A vendored module has <strong>no privileged loading path</strong>. The same call declares it, the same <code>apiVersion</code> gates it, and the same <code>import()</code> imports it, so every run exercises the route a third-party module takes. A vendored module that nobody declares does not load.</p><p><a href="./modules">Modules, vocabularies and glue</a> covers the payload vocabularies, the loading order, and what may cross between two modules.</p><h2 id="How-a-session-starts" tabindex="-1">How a session starts <a class="header-anchor" href="#How-a-session-starts" aria-label="Permalink to &quot;How a session starts {#How-a-session-starts}&quot;">​</a></h2><p>The order is fixed. Each step depends on the one before it.</p><ol><li><p>The page connects its transport and announces the protocol version it speaks. A server on another version closes the connection with a reason. Every frame is binary, so a viewer built against another framing parses no frame at all and reports nothing.</p></li><li><p>The server sends the session declaration: which modules to load, and the shape of the globe. A browser host waits for it before building its widget, so the globe is never built on an ellipsoid the server did not name.</p></li><li><p>The server replays its retained state: the latest command per <code>(module, topic)</code>, then the current window.</p></li><li><p>The Core imports every declared module concurrently, runs each <code>setup</code> in declaration order, then replays the retained commands.</p></li></ol><p>After that the session is two streams of notifications: windows and command batches travel down, events travel up, and nothing waits for a reply. The <a href="./../reference/wire/protocol">wire protocol</a> is the normative statement; the <a href="./../reference/wire/module-api">module API</a> states what a module is handed.</p><h2 id="What-this-shape-rules-out" tabindex="-1">What this shape rules out <a class="header-anchor" href="#What-this-shape-rules-out" aria-label="Permalink to &quot;What this shape rules out {#What-this-shape-rules-out}&quot;">​</a></h2><p>Three things are impossible by construction.</p><ul><li><p><strong>A module cannot change what another module drew.</strong> It may read a position through an accessor the owner exports, and draw its own primitives coincident with those. A viewer-side mutation has no author on the server, so the next window silently overwrites it (ADR-0006).</p></li><li><p><strong>The module set cannot change during a session.</strong> It is established per connection, and changing it means the client reconnects. A session whose module set changes underneath it has no coherent story for the state the departing module owned.</p></li><li><p><strong>Nothing travels upward as bytes.</strong> No arrays go up today. The server is authoritative, so bulk data that flows upward inverts the model. The frame layout was designed for both directions, and the server already decodes the region an inbound event arrives with. Only the viewer&#39;s half of the array encoder is missing, so building it later is new code and not a change to the contract.</p></li></ul>',25))])}const T=n(u,[["render",m]]);export{k as __pageData,T as default};
